// #3454 acceptance: what the comment ratchet doesn't count (AC4: a marker another lint reads, with its reason, and a
// license notice) and what is out of its scope (AC5: a generated file, vendor/ and tests/acceptance/). Each exempt file
// is a file the list doesn't hold, so one counted line would fail it; each test then shows the same repository failing
// on the comment that isn't exempt, so a guard that passes everything fails the test.
import test from 'node:test';
import { LISTED, assertFailsNaming, assertNotNamed, assertPasses, base, drop, guard, guardCommand, put } from './helpers.mjs';

/** A test file whose wait is bounded by a timer; `mark` is the comment line above the timer, `after` the one on its line. */
const bounded = ({ mark = null, after = '' } = {}) => [
  "import { once } from 'node:events';",
  "import { expect, it } from 'vitest';",
  "import { start } from './server';",
  '',
  "it('serves once ready, or fails within 30 s', async () => {",
  '  const server = start();',
  '  const deadline = new Promise((_, reject) => {',
  ...(mark === null ? [] : [`    ${mark}`]),
  `    setTimeout(() => reject(new Error('no ready event within 30 s')), 30_000);${after}`,
  '  });',
  "  await Promise.race([once(server, 'ready'), deadline]);",
  '  expect(server.ready).toBe(true);',
  '});',
  '',
].join('\n');

test('#3454.8e62c50b AC4: a planted // deadline: bounds the wait beside a timer passes, on the line above it and on its line; // deadline with no reason fails the lint lane, naming the file', (t) => {
  guardCommand();
  const cwd = base(t);
  const TIMED = 'packages/fixture/test/ready.test.ts';
  put(cwd, TIMED, bounded());
  assertPasses(guard(cwd), `(the twin of ${TIMED}, with no comment)`);
  put(cwd, TIMED, bounded({ mark: '// deadline: bounds the wait' }));
  assertPasses(guard(cwd), '(// deadline: bounds the wait on the line above the timer)');
  put(cwd, TIMED, bounded({ after: ' // deadline: bounds the wait' }));
  assertPasses(guard(cwd), "(// deadline: bounds the wait on the timer's line)");
  // The marker's word alone is no reason: a lane that takes it passes these two.
  put(cwd, TIMED, bounded({ mark: '// deadline' }));
  const bare = guard(cwd);
  assertFailsNaming(bare, TIMED, '(// deadline with no reason on the line above the timer)');
  assertNotNamed(bare, LISTED);
  put(cwd, TIMED, bounded({ mark: '// deadline:' }));
  assertFailsNaming(guard(cwd), TIMED, '(// deadline: with nothing after the colon)');
  put(cwd, TIMED, bounded({ after: ' // deadline' }));
  assertFailsNaming(guard(cwd), TIMED, "(// deadline with no reason on the timer's line)");
});

/** Ported code under `head`, two comment lines at the top of the file. */
const ported = (head) => [...head, 'export function clamp(n: number, low: number, high: number): number {', '  return Math.min(high, Math.max(low, n));', '}', ''].join('\n');
const NOTICE = ['// Copyright (c) 2026 the Fixture contributors (https://example.invalid/fixture).', '// Licensed under the Apache License, Version 2.0: https://example.invalid/fixture/LICENSE-2.0'];

test('#3454.8e62c50b AC4: a two-line license notice passes; the same two lines saying something else fail the lint lane, naming the file', (t) => {
  guardCommand();
  const cwd = base(t);
  const PORTED = 'packages/fixture/src/clamp.ts';
  put(cwd, PORTED, ported([]));
  assertPasses(guard(cwd), `(the twin of ${PORTED}, with no comment)`);
  put(cwd, PORTED, ported(NOTICE));
  assertPasses(guard(cwd), '(a two-line license notice above the code)');
  put(cwd, PORTED, ported(['// Keeps a number between two bounds.', '// The low bound wins when the two cross.']));
  const result = guard(cwd);
  assertFailsNaming(result, PORTED, '(two comment lines that are no license notice)');
  assertNotNamed(result, LISTED);
});

/** Code with five comment lines of the ordinary kind; `head` goes above it. */
const commented = (head = []) => [
  ...head,
  '/**',
  ' * Joins the parts of a path.',
  ' */',
  'export function joined(parts) {',
  '  // one separator between two parts',
  "  return parts.join('/'); // never a trailing one",
  '}',
  '',
].join('\n');

test('#3454.c7f7a59e AC5: a generated file with comments passes; the same comments in a hand-written file beside it fail the lint lane, naming it', (t) => {
  guardCommand();
  const cwd = base(t);
  const GENERATED = 'packages/fixture/src/shapes.generated.ts';
  const WRITTEN = 'packages/fixture/src/shapes.ts';
  assertPasses(guard(cwd), '(every listed file at its ceiling)');
  put(cwd, GENERATED, commented(['// @generated by scripts/fixture-shapes.mjs from shapes.json. Do not edit.']));
  const exempt = guard(cwd);
  assertNotNamed(exempt, GENERATED);
  assertPasses(exempt, `(${GENERATED} says in its first line that it is generated)`);
  put(cwd, WRITTEN, commented());
  const result = guard(cwd);
  assertFailsNaming(result, WRITTEN, "(the same comments in a hand-written file the list doesn't hold)");
  assertNotNamed(result, GENERATED);
});

test('#3454.c7f7a59e AC5: a file under vendor/ with comments passes; the same file outside vendor/ fails the lint lane, naming it', (t) => {
  guardCommand();
  const cwd = base(t);
  const VENDORED = 'vendor/fixture/joined.js';
  const OURS = 'packages/fixture/src/joined.js';
  assertPasses(guard(cwd), '(every listed file at its ceiling)');
  put(cwd, VENDORED, commented());
  const exempt = guard(cwd);
  assertNotNamed(exempt, VENDORED);
  assertPasses(exempt, `(${VENDORED} is vendored)`);
  put(cwd, OURS, commented());
  const result = guard(cwd);
  assertFailsNaming(result, OURS, "(the same comments in a file of ours the list doesn't hold)");
  assertNotNamed(result, VENDORED);
  drop(cwd, OURS);
  assertPasses(guard(cwd), '(with the planted file gone, the vendored one still passes)');
});

test('#3454.c7f7a59e AC5: a file under tests/acceptance/ with comments passes; the same file outside it fails the lint lane, naming it', (t) => {
  guardCommand();
  const SUITE = 'tests/acceptance/9001/joined.test.mjs';
  const OURS = 'tests/fixture-joined.test.mjs';
  // The suite's file is part of the base commit: a blind suite that has landed, which no change may edit.
  const cwd = base(t, { [SUITE]: commented() });
  const exempt = guard(cwd);
  assertNotNamed(exempt, SUITE);
  assertPasses(exempt, `(${SUITE} is a blind suite's file)`);
  put(cwd, OURS, commented());
  const result = guard(cwd);
  assertFailsNaming(result, OURS, "(the same comments in a test file of ours the list doesn't hold)");
  assertNotNamed(result, SUITE);
});
